head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > useFilterList]<br/>GridView 컴포넌트의 Header Column 에 FilterList 기능을 활성화할지 설정합니다.",
    "validation" : [
        "true 설정 시, 해당 Column 에 CustomFilter 와 FilterList 기능이 활성화됩니다.",
        "true 설정 시, FilterList 는 해당 Column 의 데이터를 동적으로 목록화하여 제공하는 기능입니다.",
        "false 설정 시, 해당 Column 에 CustomFilter 기능만 활성화됩니다.",
        "미설정 시, 해당 Column 에 CustomFilter 기능만 활성화됩니다.",
        "RowNum, RowStatus Column 의 Header 에는 useFilter 속성을 포함하여 모든 속성을 설정할 수 없습니다.",
        "FilterList 기능의 데이터 목록은 동적으로 변경되며 다른 Column 에 의해 필터가 적용된 경우 실제 화면에 표시되는 데이터만 목록에 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // useFilterList : '' 미설정(기본 false) / 'true' / 'false' (공통 gdl_boolean → getText())
    let vUseFilterList = con_useFilterList.getText();

    // Property : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    let properties = {};
    if (vUseFilterList === 'true') {
        properties.useFilterList = true;
    } else if (vUseFilterList === 'false') {
        properties.useFilterList = false;
    }

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] col1~col4 Header Column 은 useFilter=true (필터 아이콘 표시)\nRowNum / RowStatus Column 은 useFilter 등 속성 미적용 (필터 아이콘 없음)\nuseFilterList = ' + (vUseFilterList === '' ? '(미설정=기본 false)' : vUseFilterList) + '\n[절차] useFilter 컬럼 헤더의 필터 아이콘 클릭 -> (useFilterList=true 이면 사용자필터 클릭) 후 팝업 유형 확인 버튼 클릭\n[확인] true 이면 FilterList(체크박스 목록) 팝업, false / 미설정이면 CustomFilter(입력) 팝업 / RowNum, RowStatus 헤더에는 필터 아이콘 없음"', '', 'label1');

    // dataList 생성 (4행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // useFilter="true" Header Column + RowNum / RowStatus Column 을 가진 gridView 동적 생성
    await scwin.createUseFilterGridView(cList);
}



// useFilter="true" Header Column 을 가진 gridView 동적 생성
//  (createBasicGridView 는 useFilter 미지원 → 인라인 구성으로 useFilter 전제조건 충족)
//  rowNumVisible / rowStatusVisible = true 로 RowNum / RowStatus Column 표시(@spec1 : 이들 Header 에는 필터 미적용)
scwin.createUseFilterGridView = async function (cList) {
    let grp_comp = document.querySelector('.tc_group_basic');
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' rowNumVisible="true" rowStatusVisible="true" rowNumHeaderValue="No." rowStatusHeaderValue="St." checkAllType="false" id="" dataList="data:dlt_bind" style="width:560px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="column1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column2" value="col2" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4" useFilter="true"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 필터 팝업 유형 확인 :
//  사용자가 useFilter 컬럼의 필터 아이콘을 클릭해 팝업을 연 뒤 이 버튼을 누르면
//  열린 팝업이 FilterList(.w2grid_customFilter_list) 인지 CustomFilter(.w2grid_customFilter) 인지 확인.
//  + RowNum / RowStatus Header 에 필터 아이콘(input.w2grid_customFilter_open) 이 없는지 확인.
//  (필터 아이콘 클릭 자체는 사용자 액션 → 별도 트리거 버튼 생성하지 않음)
scwin.btn_checkFilter_onclick = function (e) {
    let scb = wf_body_bottom.getObj("scwin");

    // 설정된 옵션값
    scb.setReturnValue("[옵션] useFilterList : " + target1.options.useFilterList);

    // 열린 팝업 유형 (FilterList vs CustomFilter)
    let listPopup = document.querySelector(".w2grid_customFilter_list");
    let customPopup = document.querySelector(".w2grid_customFilter");
    let hasList = !!listPopup;
    let hasCustom = !!customPopup;
    if (!hasList && !hasCustom) {
        scb.setReturnValue("열린 필터 팝업이 없습니다. useFilter 컬럼 헤더의 필터 아이콘을 먼저 클릭하세요.");
    } else {
        scb.setReturnValue("FilterList 팝업(.w2grid_customFilter_list) 표시 : " + hasList + " / CustomFilter 팝업(.w2grid_customFilter) 표시 : " + hasCustom);
    }

    // RowNum / RowStatus Header 필터 아이콘 유무
    let rowNumTh = document.querySelector("[id*='_headerRowNumber']");
    let rowStatusTh = document.querySelector("[id*='_headerRowStatus']");
    let rowNumHasFilter = rowNumTh ? !!rowNumTh.querySelector("input.w2grid_customFilter_open") : null;
    let rowStatusHasFilter = rowStatusTh ? !!rowStatusTh.querySelector("input.w2grid_customFilter_open") : null;
    scb.setReturnValue("RowNum Header 필터 아이콘 : " + rowNumHasFilter + " / RowStatus Header 필터 아이콘 : " + rowStatusHasFilter);
}
